import{z as A,x as B,o as r,c as p,q as n,j as s,D as E,d as e,s as o,S as i,b as l}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"危险能力评测","description":"","frontmatter":{"title":"危险能力评测","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dangerous-capability-eval.md","filePath":"llm/dangerous-capability-eval.md","lastUpdated":1791063341000}'),d={name:"llm/dangerous-capability-eval.md"};function m(h,a,u,c,f,_){const t=B("Mermaid");return r(),p("div",null,[a[2]||(a[2]=n('<h1 id="危险能力评测" tabindex="-1">危险能力评测 <a class="header-anchor" href="#危险能力评测" aria-label="Permalink to &quot;危险能力评测&quot;">​</a></h1><div class="epigraph"><p>门槛评测问的是「在受控访问下能否完成高后果任务」，不是再刷一道开放知识榜。细节默认不公开到可复现攻击的粒度。</p><footer>—— Shevlane 等对极端风险评测的框架；实验室实践见 DeepMind 危险能力评估与各家 RSP</footer></div><p><a href="/llm/human-eval-protocol">上一课</a>把人评写成可审计协议。高后果能力不能靠 Arena 口味或 MMLU。本课写危险能力评测的<strong>设计原则</strong>。缺口是仪器：域专家、工具隔离、与<a href="/llm/safety-levels-rsp">安全等级</a>挂钩的门禁。后课红队是同一门禁下的对抗探测，不是另一张知识卷。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Shevlane 等人把「极端风险」评测与普通能力评测分开：对象是能否辅助生物、网络、自主复制与大规模操控等<strong>高后果任务</strong>。Phuong 等人在 DeepMind 的评估里用专家任务与脚手架，测的是上限（充分引出后还能做什么），不是默认聊天套话。与<a href="/llm/scheming-evals">谋划评测</a>的差别：本课管「有没有能力」，谋划管「是否在考场上藏能力」。</p><p><span class="marginnote">「脚手架」（scaffolding）指包在模型外面的工具与流程代码：搜索、终端、多轮重试、子任务分解。同一个模型配上不同脚手架，能完成的事天差地别——就像同一个人，徒手和带着全套工具箱能干的活不一样。所以危险能力评测必须把脚手架等级写进协议，否则「能不能做到」没有答案。</span></p><p>公开基准一旦细到可操作步骤，就变成教程。因此协议必须分层：公开的是任务类别、是否触发门槛、谁评的；不公开的是可直接挪用的材料。这与普通学术可复现性冲突，必须在模型卡里写明「不可外部复核的部分及内部审计方」。</p><p><span class="marginnote">本课只讨论评测结构：专家、隔离环境、与 RSP 门槛的对应。不描述具体危害任务的操作内容。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>最小结构：任务族与后果等级；访问条件（工具、网络、专家协助是否允许）；引出预算（下一课会展开）；评分由领域专家按 rubric，不由通用 LLM 法官；预先规定「触发再评测 / 限制部署」的阈值。与普通 harness 隔离：不同存储、不同人员、不同日志策略。</p><p><span class="marginnote">rubric（评分细则）就是把「专家怎么打分」写成一张分项清单，例如「完成第 1 到第 5 步各计几分、哪几步算触发门槛」。它让两个专家评同一个任务时给分接近，也让「接近门槛」这种判断有据可查，而不是凭印象。</span></p><p>结果写成门槛判断（低于 / 接近 / 超过），附不确定性，而不是精确到小数的排行榜。小数会制造假鉴别力，也会刺激对公开代理题的优化。</p>',12)),(r(),s(i,null,{default:E(()=>[o(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAM%5B%22%E4%BB%BB%E5%8A%A1%E6%97%8F%E4%B8%8E%E5%90%8E%E6%9E%9C%22%5D%20--%3E%20ACC%5B%22%E8%AE%BF%E9%97%AE%E4%B8%8E%E9%9A%94%E7%A6%BB%22%5D%0A%20%20ACC%20--%3E%20ELI%5B%22%E5%BC%95%E5%87%BA%E9%A2%84%E7%AE%97%22%5D%0A%20%20ELI%20--%3E%20EXP%5B%22%E9%A2%86%E5%9F%9F%E4%B8%93%E5%AE%B6%E8%AF%84%E5%88%86%22%5D%0A%20%20EXP%20--%3E%20GATE%5B%22RSP%20%E9%97%A8%E6%A7%9B%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[e("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,[e("危险能力往往不是零样本聊天里的一道题，而是"),l("strong",null,"工具 + 专家级提示 + 迭代"),e("后的可达集。只测裸模型会低估；无限脚手架会高估成「人类团队」。协议要钉死脚手架等级，使两次评估可比。阈值应连到部署许可，而不是连到公关稿。")],-1)),(r(),s(i,null,{default:E(()=>[o(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20M%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20Z%5B%22%E9%9B%B6%E6%A0%B7%E6%9C%AC%E8%A3%B8%E9%97%AE%22%5D%20--%3E%20U%5B%22%E4%BD%8E%E4%BC%B0%E7%9C%9F%E5%AE%9E%E4%B8%8A%E9%99%90%22%5D%0A%20%20M%20--%3E%20F%5B%22%E5%9B%BA%E5%AE%9A%E8%84%9A%E6%89%8B%E6%9E%B6%2B%E5%9B%BA%E5%AE%9A%E9%A2%84%E7%AE%97%22%5D%20--%3E%20C%5B%22%E4%B8%A4%E6%AC%A1%E8%AF%84%E4%BC%B0%E5%8F%AF%E6%AF%94%22%5D%0A%20%20M%20--%3E%20S%5B%22%E6%97%A0%E9%99%90%E4%B8%93%E5%AE%B6%E8%84%9A%E6%89%8B%E6%9E%B6%22%5D%20--%3E%20O%5B%22%E9%AB%98%E4%BC%B0%E6%88%90%E4%BA%BA%E7%B1%BB%E5%9B%A2%E9%98%9F%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">常见误区：以为危险能力评测就是问模型「你怎么做 X」，看它答不答。实际上高后果任务几乎都需要工具与多轮迭代，单轮问答里「拒绝回答」不等于「没有能力」；反过来，把整个研究团队的人机流程都给它，测出的又不是模型自己的水平。测的是中间那个固定脚手架的工作点。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不提供攻击配方，不把代理题细到可操作。下一课红队评测转向对抗性探测：在同一隔离纪律下找规约漏洞，而不是测领域上限。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>危险能力评测是门槛判断，对象是高后果任务的可达集。</li><li>专家 + 隔离 + 固定引出预算；细节不可公开到教程粒度。</li><li>与谋划评测分工：能力上限对条件策略。</li><li>出处：Shevlane 等极端风险评测框架；Phuong 等危险能力评估；RSP 课。</li></ul>',5))])}const b=A(d,[["render",m]]);export{C as __pageData,b as default};
